from pathlib import Path
import base64
import re

ROOT = Path.cwd()
SD_HEADER_API = base64.b64decode("").decode("utf-8")
SD_CONSTANTS = base64.b64decode("").decode("utf-8")
SD_HELPERS = base64.b64decode("").decode("utf-8")
SD_METHODS = base64.b64decode("").decode("utf-8")
EXPORT_IMPL = base64.b64decode("").decode("utf-8")
DISPLAY_HELPER = base64.b64decode("").decode("utf-8")
BOOT_LIBRARY_BLOCK = base64.b64decode("").decode("utf-8")
CANONICALIZE_HELPER = base64.b64decode("").decode("utf-8")
SD_IMPORT_BLOCK = base64.b64decode("").decode("utf-8")
README_APPEND = base64.b64decode("").decode("utf-8")
CHANGELOG_ENTRY = base64.b64decode("").decode("utf-8")
CHECKLIST_APPEND = base64.b64decode("").decode("utf-8")
TODO_APPEND = base64.b64decode("").decode("utf-8")

def read(rel):
    return (ROOT / rel).read_text(encoding="utf-8")

def write(rel, text):
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding="utf-8")

def replace_once(text, old, new, label):
    if old not in text:
        raise RuntimeError(label + ": trecho esperado nao encontrado")
    return text.replace(old, new, 1)

def replace_cpp_function(text, marker, replacement):
    start = text.find(marker)
    if start < 0:
        raise RuntimeError("Funcao nao encontrada: " + marker)
    brace = text.find("{", start)
    if brace < 0:
        raise RuntimeError("Abertura nao encontrada: " + marker)
    depth = 0
    in_string = False
    escape = False
    line_comment = False
    block_comment = False
    i = brace
    while i < len(text):
        c = text[i]
        n = text[i + 1] if i + 1 < len(text) else ""
        if line_comment:
            if c == "\n": line_comment = False
        elif block_comment:
            if c == "*" and n == "/":
                block_comment = False
                i += 1
        elif in_string:
            if escape: escape = False
            elif c == "\\": escape = True
            elif c == '"': in_string = False
        else:
            if c == "/" and n == "/":
                line_comment = True
                i += 1
            elif c == "/" and n == "*":
                block_comment = True
                i += 1
            elif c == '"': in_string = True
            elif c == "{": depth += 1
            elif c == "}":
                depth -= 1
                if depth == 0:
                    return text[:start] + replacement.rstrip() + "\n" + text[i + 1:]
        i += 1
    raise RuntimeError("Fechamento nao encontrado: " + marker)

# config.h
p = "include/config.h"
s = read(p)
if "0.7.0-preview.2-touch" not in s:
    raise RuntimeError("baseline esperada 0.7.0-preview.2-touch")
s = re.sub(
    r'constexpr char APP_VERSION\[\]\s*=\s*\"[^\"]+\"\s*;',
    'constexpr char APP_VERSION[] = "0.7.0-preview.3-touch";',
    s, count=1)
anchor = "constexpr uint8_t MAX_DEVICE_CARDS = 128;\n"
if anchor not in s:
    raise RuntimeError("MAX_DEVICE_CARDS anchor ausente")
s = s.replace(anchor, anchor + "\n// O array em RAM e catalogo leve. Conteudo textual completo fica no SD.\nconstexpr bool SD_FIRST_LIBRARY = true;\n", 1)
write(p, s)

# sd_card_service.h
p = "include/sd_card_service.h"
s = read(p)
anchor = "    bool exportLibrary(\n"
pos = s.find(anchor)
if pos < 0:
    raise RuntimeError("exportLibrary anchor ausente no header")
if 'canonicalLibraryAvailable()' not in s:
    s = s[:pos] + SD_HEADER_API + '\n' + s[pos:]
write(p, s)

# sd_card_service.cpp constants/helpers
p = "src/sd_card_service.cpp"
s = read(p)
anchor = 'constexpr const char* EXPORT_DIR =\n    "/mnemos/export";\n'
if anchor not in s:
    raise RuntimeError("EXPORT_DIR anchor ausente")
if "CANONICAL_LIBRARY_PATH" not in s:
    s = s.replace(anchor, anchor + '\n\n' + SD_CONSTANTS + '\n', 1)
ns_end = s.find("}  // namespace\n")
if ns_end < 0:
    raise RuntimeError("namespace end ausente")
if "serializeCardLine(" not in s[:ns_end]:
    s = s[:ns_end] + SD_HELPERS + '\n\n' + s[ns_end:]

# ensureFolders library dir
folder_old = '''    if (!SD.exists(EXPORT_DIR)) {\n        if (!SD.mkdir(EXPORT_DIR)) {\n            return false;\n        }\n    }\n\n    return true;\n}\n'''
folder_new = '''    if (!SD.exists(EXPORT_DIR)) {\n        if (!SD.mkdir(EXPORT_DIR)) {\n            return false;\n        }\n    }\n\n    if (!SD.exists(LIBRARY_DIR)) {\n        if (!SD.mkdir(LIBRARY_DIR)) {\n            return false;\n        }\n    }\n\n    return true;\n}\n'''
if 'SD.mkdir(LIBRARY_DIR)' not in s:
    s = replace_once(s, folder_old, folder_new, "ensureFolders")

marker = "SdImportResult SdCardService::importDeckFile("
pos = s.find(marker)
if pos < 0:
    raise RuntimeError("importDeckFile marker ausente")
if "SdCardService::canonicalLibraryAvailable()" not in s:
    s = s[:pos] + SD_METHODS + '\n\n' + s[pos:]
s = replace_cpp_function(s, "bool SdCardService::exportLibrary(", EXPORT_IMPL)
write(p, s)

# main.cpp
p = "src/main.cpp"
s = read(p)
if "CardDefinition displayCardBuffer;" not in s:
    s = replace_once(s, "String sdStatus;\n", "String sdStatus;\n\nCardDefinition displayCardBuffer;\n", "sdStatus global")
marker = "void renderQuestion()"
pos = s.find(marker)
if pos < 0:
    raise RuntimeError("renderQuestion marker ausente")
if "const CardDefinition& cardForDisplay()" not in s:
    s = s[:pos] + DISPLAY_HELPER + '\n\n' + s[pos:]
s = s.replace(
    "    display.showQuestion(\n        engine->currentCard(),\n        engine->currentPosition(),\n        engine->sessionCount());",
    "    display.showQuestion(\n        cardForDisplay(),\n        engine->currentPosition(),\n        engine->sessionCount());", 1)
s = s.replace(
    "    display.showSelfAssessment(\n        engine->currentCard(),\n        engine->currentPosition(),\n        engine->sessionCount());",
    "    display.showSelfAssessment(\n        cardForDisplay(),\n        engine->currentPosition(),\n        engine->sessionCount());", 1)
s = s.replace(
    "        showObjectiveFeedback(\n            engine->currentCard(),",
    "        showObjectiveFeedback(\n            cardForDisplay(),", 1)

# setup library block
start = s.find("    if (\n        !storage.loadLibrary(\n")
end = s.find("    backendSync.begin();", start)
if start < 0 or end < 0:
    raise RuntimeError("setup library block nao encontrado")
s = s[:start] + BOOT_LIBRARY_BLOCK + '\n\n' + s[end:]

# SD import action
old_import = '''                    const SdImportResult result = sdCardService.importDeckFile(\n                        sdPaths[argument], cards, states, Config::MAX_DEVICE_CARDS, cardCount);\n                    if (result.ok) {\n                        storage.saveLibrary(cards, states, cardCount);\n                        rebuildEngine();\n                        sdStatus = "Importados " + String(result.added) +\n                            ", atualizados " + String(result.updated) +\n                            ", ignorados " + String(result.skipped);\n                    } else {\n                        sdStatus = result.error;\n                    }\n                    renderStorage();'''
if old_import not in s:
    raise RuntimeError("SD import action block ausente")
s = s.replace(old_import, SD_IMPORT_BLOCK, 1)

# helper must live before setup(), never inside loop()
setup_pos = s.find("void setup()")
if setup_pos < 0:
    raise RuntimeError("setup marker ausente")
if "void canonicalizeActiveLibraryIfPossible()" not in s:
    s = s[:setup_pos] + CANONICALIZE_HELPER + '\n\n' + s[setup_pos:]

# post LocalLink update
old = '''    ) {\n        rebuildEngine();\n\n        Serial.printf(\n            "[app] biblioteca atualizada "\n            "por Wi-Fi local: %u cartoes\\n",'''
new = '''    ) {\n        canonicalizeActiveLibraryIfPossible();\n        rebuildEngine();\n\n        Serial.printf(\n            "[app] biblioteca atualizada "\n            "por Wi-Fi local: %u cartoes\\n",'''
if old in s:
    s = s.replace(old, new, 1)
else:
    raise RuntimeError("LocalLink update block nao encontrado")

# post backend update
old = '''        if (\n            backendSync.\n                consumeLibraryUpdated()\n        ) {\n            rebuildEngine();\n'''
new = '''        if (\n            backendSync.\n                consumeLibraryUpdated()\n        ) {\n            canonicalizeActiveLibraryIfPossible();\n            rebuildEngine();\n'''
if old not in s:
    raise RuntimeError("backend update block nao encontrado")
s = s.replace(old, new, 1)
write(p, s)

# capabilities
p = "src/local_link_service.cpp"
s = read(p)
anchor = 'doc["features"]["sdStorage"] = true;'
if anchor in s and "lazyCardContent" not in s:
    s = s.replace(anchor, anchor + '\n        doc["features"]["sdFirstLibrary"] = true;\n        doc["features"]["lazyCardContent"] = true;', 1)
write(p, s)

p = "src/backend_sync_service.cpp"
s = read(p)
anchor = 'doc["capabilities"]["microSD"] = true;'
if anchor in s and "lazyCardContent" not in s:
    s = s.replace(anchor, anchor + '\n    doc["capabilities"]["sdFirstLibrary"] = true;\n    doc["capabilities"]["lazyCardContent"] = true;', 1)
write(p, s)

# docs
p = "README.md"
s = read(p)
if "## Biblioteca SD-first" not in s:
    s += '\n\n' + README_APPEND + '\n'
write(p, s)

p = "CHANGELOG.md"
s = read(p)
first, rest = s.split('\n', 1)
s = first + '\n\n' + CHANGELOG_ENTRY + '\n\n' + rest.lstrip('\n')
write(p, s)

p = "docs/TEST_CHECKLIST.md"
s = read(p)
s += '\n\n' + CHECKLIST_APPEND + '\n'
write(p, s)

todo_path = ROOT / "../../docs/integration/T5_TOUCH_EXTERNAL_TODO.md"
if todo_path.exists():
    todo = todo_path.read_text(encoding="utf-8")
    if "## Biblioteca SD-first — paginação" not in todo:
        todo += '\n\n' + TODO_APPEND + '\n'
    todo_path.write_text(todo, encoding="utf-8")

guards = {
    "version": "0.7.0-preview.3-touch" in read("include/config.h"),
    "canonical api": "canonicalLibraryAvailable" in read("include/sd_card_service.h"),
    "canonical file": "cards.ndjson" in read("src/sd_card_service.cpp"),
    "hydrate": "SdCardService::hydrateCard" in read("src/sd_card_service.cpp"),
    "display": "cardForDisplay()" in read("src/main.cpp"),
    "import": "importDeckFileToCanonical" in read("src/main.cpp"),
    "helper outside loop": read("src/main.cpp").find("void canonicalizeActiveLibraryIfPossible()") < read("src/main.cpp").find("void setup()"),
}
bad = [k for k,v in guards.items() if not v]
if bad:
    raise RuntimeError("validacao falhou: " + ", ".join(bad))

print("[OK] 0.7.0-preview.3-touch aplicada")
print("[OK] SD canonico + catalogo leve")
print("[OK] hidratacao sob demanda")
print("[OK] helper de canonicalizacao fora do loop")